"""flow.ladder: generated by the graph.py split (P1)."""

from __future__ import annotations

from typing import Any, Literal

from langgraph.errors import NodeError
from langgraph.types import Command

from ..flow import gates, outcome
from ..flow.gates import ANSWER_REPAIR_TARGETS, DELIVERY_RETRY_MAX, PREPARE_GATE
from .. import state as state_mod
from ..runtime import stage_services
from ..runtime.policy import PolicyError
from ..state import CfuDesignState


def _route_input_target(state: CfuDesignState) -> str:
    """Conditional edge: which benchmark-preparation node to run."""
    return _route_kind(state)[1]


def _route_kind(state: CfuDesignState) -> tuple[str, str]:
    kind = state.get("input_kind") or state.get("input_mode", "natural_language")
    if kind not in ("c_project", "natural_language", "embench"):
        kind = "natural_language"
    if kind == "embench":
        return kind, "prepare_embench_benchmark"
    return kind, ("prepare_c_project_profile" if kind == "c_project" else "create_benchmark_project")


#: Failures the benchmark-preparation rungs treat as a clean, attributable stop.
PREPARE_FAILURES = (PolicyError, ValueError, OSError)


def prepare_failure_handler(
    state: CfuDesignState, error: NodeError,
) -> Command[Literal["review_and_route"]]:
    """Node-level LangGraph error handler for the benchmark-preparation rungs.

    ``NodeError`` is required for runtime parameter injection, not just typing.
    The handler is a separate node and does not inherit the failed node's edges,
    so its Command must explicitly route to review after updating the failed gate.

    Registered through ``add_node(..., error_handler=...)`` (see
    ``flow/policies.py``) instead of a ``try/except`` inside each node. The
    accepted set stays exactly as narrow as it was in the nodes: an unexpected
    exception is a bug, not a denied read, so it is re-raised and the run still
    aborts loudly rather than being "repaired" as if it were a design failure.
    """
    exc = getattr(error, "error", error)
    if not isinstance(exc, PREPARE_FAILURES):
        raise exc
    node = str(getattr(error, "node", "") or PREPARE_GATE)
    return Command(update=_prepare_failure_update(state, node, exc), goto="review_and_route")


def _prepare_failure_update(state: CfuDesignState, node: str, exc: Exception) -> dict[str, Any]:
    """Turn a benchmark-preparation policy/input error into a clean failure.

    A denied read (for example a C project outside the allowlist) must stop the
    run with ``status=failed`` instead of raising out of the graph.
    """
    message = f"{node} failed: {exc}"
    # Reporting a failure must never mint a run identity: a caller that never
    # went through load_context (and so has no run_id) must not create a fresh
    # run directory just to record its own failure. A real run always has one.
    if str(state.get("run_id", "") or "").strip():
        try:
            stage_services._artifacts_for_stage(state, "prepare_benchmark").write_yaml(
                "prepare_benchmark",
                "04_benchmark/manifest.yaml",
                {"kind": "failed", "node": node, "error": str(exc)},
                status="failed",
            )
        except (PolicyError, OSError, ValueError):
            # Reporting the failure must never mask the original error.
            pass
    return {
        "benchmark_project": {"kind": "failed", "notes": [message]},
        "stage_jobs": "review",
        "stopped_at": PREPARE_GATE,
        "errors": [message],
        **outcome.stage_result(state, rung=PREPARE_GATE, ok=False, node=node,
                               next="review_and_route", errors=[str(exc)], history=message),
    }


def _prepare_gates(state: CfuDesignState, node: str, next_node: str) -> dict:
    return {
        **state.get("gates", {}),
        PREPARE_GATE: {"ok": True, "node": node, "next": next_node},
    }


def _route_after_prepare(state: CfuDesignState) -> str:
    gate = (state.get("gates", {}) or {}).get(PREPARE_GATE, {}) or {}
    return str(gate.get("next") or "review_and_route")


def _route_after_profile(state: CfuDesignState) -> str:
    """Executed preconditions fail closed; explicit planning remains advisory."""
    gate = (state.get("gates") or {}).get("profile") or {}
    if gate and not gate.get("ok") and not gate.get("skipped"):
        return "review_and_route"
    return "extract_hotspot"


def _route_after_review(state: CfuDesignState) -> str:
    return gates._rung_next(state, "review", "final_report")


def _delivery_retry_transition(
    state: CfuDesignState,
    rung: str,
    target: str,
    ok: bool,
    rejection: bool,
) -> tuple[dict, str] | None:
    """Retry a rejected delivery without spending the design-repair budget.

    ``rejection`` is True only when the implementation stage produced no applied
    change (a deterministic delivery/protocol error). A design that was
    delivered but fails its build is a real repair and keeps using ``--max-iters``.
    """
    if ok or not rejection:
        return None
    retries = int(state.get("delivery_retries", 0) or 0)
    if retries >= DELIVERY_RETRY_MAX:
        return None
    note = (
        f"{rung} not reached: the {target} delivery was rejected by a deterministic "
        f"check and nothing was applied; correcting the delivery "
        f"(retry {retries + 1}/{DELIVERY_RETRY_MAX}) without spending repair budget."
    )
    return {
        "delivery_retries": retries + 1,
        "iteration": int(state.get("iteration", 0) or 0) + 1,
        "stage_jobs": target,
        "repair_entry": {"kind": "delivery", "target": target,
                         "iteration": int(state.get("iteration", 0) or 0) + 1, "route_used": False},
        "errors": [note],
        "iteration_history": state_mod.append_history(state, note),
    }, target


def _ladder_transition(
    state: CfuDesignState,
    rung: str,
    *,
    ok: bool,
    default: str,
    repair_target: str | Any,
    skipped: bool = False,
    repair_kind: str | None = None,
    verification_submission: bool | None = None,
) -> tuple[dict, str]:
    """Decide a rung's successor and the bookkeeping that goes with it.

    ``--max-iters`` counts candidate submissions to the verification ladder.
    A failed verification rung may be repaired only if another submission slot
    remains. Answer-only repairs and pre-verification implementation reroutes
    have separate bounded pools.
    """
    if ok or skipped:
        return {}, default
    target = repair_target(state) if callable(repair_target) else repair_target
    if repair_kind not in (None, "answer", "design", "preverify"):
        raise ValueError("repair_kind must be answer, design, or preverify")
    answer_repair = repair_kind == "answer" or (repair_kind is None and target in ANSWER_REPAIR_TARGETS)
    verify_rung = (rung in gates.LADDER_RUNGS) if verification_submission is None else verification_submission

    if answer_repair:
        budget_kind = "answer"
        budget_left = gates._answer_repairs_left(state)
        if verify_rung:
            budget_left = budget_left and gates._verify_submissions_left(state)
    elif verify_rung:
        budget_kind = "design"
        budget_left = gates._verify_submissions_left(state)
    else:
        budget_kind = "preverify"
        budget_left = gates._preverify_repairs_left(state)

    counter_key, cap = {
        "answer": ("answer_repairs_used", gates.answer_repairs_max(state)),
        "design": ("repairs_used", gates.max_repairs(state)),
        "preverify": ("preverify_repairs_used", gates.preverify_repairs_max(state)),
    }[budget_kind]
    if budget_left:
        consumed = int(state.get(counter_key, 0) or 0)
        note = f"{rung} failed; repairing {target} (repair {consumed + 1}/{cap})."
        if verify_rung:
            note = (
                f"{rung} failed after verification submission "
                f"{int(state.get('verify_submissions', 0) or 0)}/"
                f"{gates.max_verify_submissions(state)}; repairing {target}."
            )
        attempts = dict(state.get("attempts", {}) or {})
        attempts[rung] = int(attempts.get(rung, 0)) + 1
        return {
            "attempts": attempts,
            counter_key: consumed + 1,
            "iteration": int(state.get("iteration", 0) or 0) + 1,
            "last_repair_target": target,
            "stage_jobs": target,
            "repair_entry": {"kind": budget_kind, "target": target,
                             "iteration": int(state.get("iteration", 0) or 0) + 1, "route_used": False},
            "errors": [note],
            "iteration_history": state_mod.append_history(state, note),
        }, target

    if verify_rung and not gates._verify_submissions_left(state):
        note = (
            f"{rung} failed and the verification-submission budget is exhausted "
            f"(--max-iters {gates.max_verify_submissions(state)}); stopping the run."
        )
    elif budget_kind == "answer":
        note = (
            f"{rung} failed and the answer-repair budget is exhausted "
            f"(--max-answer-repairs {gates.answer_repairs_max(state)}); stopping the run."
        )
    else:
        note = (
            f"{rung} failed and the pre-verification repair budget is exhausted "
            f"(--max-preverify-repairs {gates.preverify_repairs_max(state)}); stopping the run."
        )
    return {
        "stopped_at": rung,
        "stage_jobs": "review",
        "errors": [note],
        "iteration_history": state_mod.append_history(state, note),
    }, "review_and_route"


def _apply_transition(update: dict, extra: dict) -> dict:
    """Fold a ``_ladder_transition`` payload into a node's state update."""
    extra = dict(extra)
    notes = extra.pop("errors", []) or []
    if notes:
        update["errors"] = [*(update.get("errors") or []), *notes]
    update.update(extra)
    return update


def _route_after_analysis(state: CfuDesignState) -> str:
    return gates._rung_next(state, "analysis", "design_contract")


def _route_after_isa(state: CfuDesignState) -> str:
    return gates._rung_next(state, "isa", "implement")


def _route_after_implement(state: CfuDesignState) -> str:
    return gates._rung_next(state, "implementation_route", "generate_soc")


def repair_route_transition(state: CfuDesignState, route: dict) -> dict:
    """One bounded upstream rewind; never use the answer-retry pool for routing."""
    target = {"analysis": "analyze_workload", "contract": "design_contract"}.get(route.get("target"))
    if target is None:
        raise ValueError("only analysis/contract cause an upstream rewind")
    entry = state.get("repair_entry") or {}
    paid_entry = (entry.get("kind") == "design" and entry.get("target") == "implement"
                  and entry.get("iteration") == int(state.get("iteration", 0) or 0)
                  and not entry.get("route_used"))
    if paid_entry:
        note = f"Implementation repair selects {target} using its already-paid design-repair slot."
        extra, next_node = {
            "last_repair_target": target, "stage_jobs": target,
            "iteration_history": state_mod.append_history(state, note),
        }, target
    else:
        extra, next_node = _ladder_transition(
            state, "implementation_route", ok=False, default="generate_soc",
            repair_target=target, repair_kind="preverify")
    update = {"repair_route": dict(route), **extra}
    if next_node == target:
        update["repair_entry"] = {"kind": "design" if paid_entry else "preverify",
                                  "target": target, "route_used": True,
                                  "iteration": extra.get("iteration", state.get("iteration", 0))}
        preserved = {"load_context", "workload_spec", "prepare_benchmark", "profile", "hotspot", "ir"}
        if route["target"] == "contract":
            preserved.add("analysis")
        update.update({
            "gates": {key: value for key, value in (state.get("gates") or {}).items()
                      if key in preserved},
            "isa_spec": {}, "isa_spec_text": "", "isa_spec_errors": [], "design_contract": "",
            "isa_extension_base": {}, "isa_added_symbols": [], "conformance_delivery": {},
            "hardware_plan": "", "software_plan": "", "hardware_patch": "", "software_patch": "",
            "implementation_hw_summary": "", "implementation_sw_summary": "",
            "changed_design_files": [], "changed_sw_files": [], "repair_scope": "",
            "input_fingerprints": {}, "best_candidate": {}, "optimization_plan": {}, "delivered_round": 0,
            "flow_memory": {}, "stopped_at": "",
            "repair_evidence_epoch": {key: len(state.get(key) or [])
                                      for key in ("validation_results", "cost_results", "hw_attempts",
                                                  "sw_attempts", "conformance_attempts")},
        })
        if route["target"] == "analysis":
            update["workload_analysis"] = ""
    current = {**state, **update}
    update["gates"] = outcome.gate(
        current, "implementation_route", ok=False,
        rewind=outcome.Rewind(next_node, route["reason"], tuple(route["failure_ids"])),
        repair_target=route["target"], repair_diagnosis=route["diagnosis"], rolled_back=True)
    return update


def _route_after_hw_build(state: CfuDesignState) -> str:
    return gates._rung_next(state, "hw_build", "check_conformance")


def _route_after_hw_conformance(state: CfuDesignState) -> str:
    # The implementation stage already wrote the software, so the ladder simply
    # compiles it: there is no separate software-implementation rung any more.
    return gates._rung_next(state, "hw_conformance", "build_sw")


def _route_after_sw_build(state: CfuDesignState) -> str:
    target = gates._rung_next(state, "sw_build", "simulate")
    if target == "simulate" and int(state.get("flow_version", 1)) >= 2:
        return "validate_candidate"
    return target


def _route_after_validation(state: CfuDesignState) -> str:
    return gates._rung_next(state, "validation_pair", "review_and_route")


def _route_after_sim(state: CfuDesignState) -> str:
    return gates._rung_next(state, "sim", "estimate_cost")


def _route_after_cost(state: CfuDesignState) -> str:
    return gates._rung_next(state, "cost", "review_and_route")
